elecione</option><?php foreach($sources as $source):?><option value="<?=H::escape($source['tipo'].':'.$source['id'])?>"><?=H::escape($source['nome'])?> · <?=Money::format((int)$source['saldo'])?></option><?php endforeach;?></select></div><div><label class="form-label" for="reserved-value">Valor reservado (R$)</label><input class="form-control" id="reserved-value" name="valor" inputmode="decimal" required></div><button class="btn btn-uai-primary">Reservar neste objetivo</button></form><p class="small text-secondary mt-2 mb-0">Uma nova reserva para a mesma fonte atualiza seu valor anterior. O total reservado em objetivos não pode superar o saldo da fonte.</p></div></section><section class="card"><div class="card-body"><details><summary>Editar objetivo</summary><form method="post" action="<?=H::escape($basePath.'/objetivos/'.$id.'/editar')?>" class="vstack gap-2 mt-3"><?=H::fields($csrfToken)?><label>Nome<input class="form-control" name="nome" required value="<?=H::escape($goal['nome'])?>"></label><label>Finalidade<textarea class="form-control" name="finalidade" maxlength="300"><?=H::escape($goal['finalidade']??'')?></textarea></label><label>Tipo<select class="form-select" name="tipo"><?php foreach($types as $key=>$label):?><option value="<?=$key?>" <?=$goal['tipo']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Prioridade<select class="form-select" name="prioridade"><?php foreach(['alta'=>'Alta','media'=>'Média','baixa'=>'Baixa'] as $key=>$label):?><option value="<?=$key?>" <?=$goal['prioridade']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Horizonte<select class="form-select" name="horizonte"><?php foreach(['indefinido'=>'Sem prazo','curto'=>'Curto prazo','medio'=>'Médio prazo','longo'=>'Longo prazo'] as $key=>$label):?><option value="<?=$key?>" <?=$goal['horizonte']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Valor desejado<input class="form-control" name="valor_meta" inputmode="decimal" required value="<?=number_format($target/100,2,',','')?>"></label><label>Data desejada<input class="form-control" name="data_alvo" type="date" value="<?=H::escape($goal['data_alvo']??'')?>"></label><label>Aporte mensal planejado<input class="form-control" name="aporte_mensal" inputmode="decimal" value="<?=number_format((int)$goal['aporte_mensal_centavos']/100,2,',','')?>"></label><button class="btn btn-outline-secondary">Salvar</button></form></details></div></section><form method="post" action="<?=H::escape($basePath.'/objetivos/'.$id.'/arquivar')?>"><?=H::fields($csrfToken)?><button class="btn btn-outline-secondary">Arquivar objetivo</button></form><?php endif;?></div></div></div>
